-- hrm.tg_leave_types_rules: A leave type counted in hours has the unit hour and only then; a paid type is not an unpaid-leave deduction; code, counting and unit are fixed once the type has ledger entries (FR-HRM-LVE-01); refused with constraint ck_leave_types_rules.
create or replace function hrm.tg_leave_types_rules() returns trigger
language plpgsql as $fn$
begin
    if (new.counting = 'hours') <> (new.unit = 'hour') then
        raise exception 'leave type %: a type counted in hours is taken in hours, and only then', new.code
            using errcode = '23514', constraint = 'ck_leave_types_rules';
    end if;
    if new.is_paid and new.is_unpaid_deduction then
        raise exception 'leave type %: a paid type cannot be an unpaid-leave deduction', new.code
            using errcode = '23514', constraint = 'ck_leave_types_rules';
    end if;
    if tg_op = 'UPDATE'
       and (lower(new.code) is distinct from lower(old.code) or new.counting is distinct from old.counting or new.unit is distinct from old.unit
            or new.company_id is distinct from old.company_id)
       and exists (select 1 from hrm.leave_ledger l where l.company_id = old.company_id and l.leave_type_id = old.id) then
        raise exception 'leave type %: code, counting and unit cannot change once the type has ledger entries', old.code
            using errcode = '23514', constraint = 'ck_leave_types_rules';
    end if;
    return new;
end
