-- hrm.tg_leave_ledger_reversal: A leave ledger entry is never zero, and a reversal negates exactly one entry of the same employment, type and leave year, of the same kind (usage by usage_reversal), never a reversal (FR-HRM-LVE-10, FR-XM-06); refused with constraint ck_leave_ledger_reversal.
create or replace function hrm.tg_leave_ledger_reversal() returns trigger
language plpgsql as $fn$
declare
    original hrm.leave_ledger%rowtype;
begin
    if new.quantity = 0 then
        raise exception 'leave ledger: an entry of nothing is not recorded'
            using errcode = '23514', constraint = 'ck_leave_ledger_reversal';
    end if;
    if new.reverses_entry_id is null then
        if new.kind = 'usage_reversal' then
            raise exception 'leave ledger: a usage reversal names the usage it reverses'
                using errcode = '23514', constraint = 'ck_leave_ledger_reversal';
        end if;
        return new;
    end if;
    select * into original from hrm.leave_ledger where company_id = new.company_id and id = new.reverses_entry_id;
    if not found
       or original.reverses_entry_id is not null
       or original.employment_id <> new.employment_id
       or original.leave_type_id <> new.leave_type_id
       or original.leave_year <> new.leave_year
       or new.quantity <> -original.quantity
       or not (new.kind = original.kind and original.kind <> 'usage' or original.kind = 'usage' and new.kind = 'usage_reversal') then
        raise exception 'leave ledger: entry % does not reverse entry % exactly', new.id, new.reverses_entry_id
            using errcode = '23514', constraint = 'ck_leave_ledger_reversal';
    end if;
    return new;
end
